alter table public.customer_referrals add column if not exists cashback_credited_at timestamptz; alter table public.customer_referrals add column if not exists cashback_reversed_at timestamptz; alter table public.customer_referrals add column if not exists cashback_credit_month date; alter table public.customer_referrals add column if not exists ineligible_reason text; create unique index if not exists customer_cashback_one_credit_month_idx on public.customer_referrals(tenant_id,cashback_credit_month) where cashback_credited_at is not null and cashback_reversed_at is null;